-- Importa os alunos da planilha "Lista de Presença - Marangoni Poá" (aba EVOQUE - POÁ 2026).
-- Cada aluno vira uma ficha sem conta; ele assume a ficha em "Já é aluno? Faça seu acesso".
-- Pode rodar de novo: não duplica (ids fixos por nome).

-- Grade real (segunda e quarta 90 min, sexta 60 min). Confirme os horários em Mais → Grade.
delete from public.aulas where id in ('c1','c2','c3','c4','c5','c6');
on conflict (id) do nothing;
-- As técnicas agora vêm do currículo oficial de exames (dentro do app)
delete from public.tecnicas where id in ('t1','t2','t3','t4','t5','t6');

on conflict (id) do nothing;

select count(*) as "Alunos importados" from public.profiles where role = 'aluno';
